```cpp
#include <iostream>
#include <string>
#include <markdowncpp.hpp>

std::string markdownToHtml(std::string markdownText) {
    markdowncpp::Parser parser;
    markdowncpp::Buffer buffer;
    markdowncpp::Writer writer;

    // Load the Markdown text
    buffer.write(markdownText);

    // Parse the Markdown text
    parser.parse(buffer);

    // Convert the Markdown to HTML
    writer.write(parser);

    // Return the HTML output
    return writer.get();
}

int main() {
    std::string markdownText = "*This is **markdown text";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "HTML Output: " << htmlText << std::endl;
    return 0;
}
```

